using Clock=chrono::steady_clock;
static uint64_t nowms(){return chrono::duration_cast<chrono::milliseconds>(Clock::now().time_since_epoch()).count();}
static string trim(string s){size_t a=s.find_first_not_of(" \t\r\n"),b=s.find_last_not_of(" \t\r\n");return a==string::npos?string():s.substr(a,b-a+1);}
static bool number(const string&s,uint64_t&v){if(s.empty())return false;v=0;for(unsigned char c:s){if(c<'0'||c>'9'||v>(UINT64_MAX-(c-'0'))/10)return false;v=v*10+c-'0';}return v>0;}
struct Config {string listen,root;uint64_t maxconn,header,htime,idle,wtime,maxreq,pipe;};
static bool config(const char* path,Config& c){ifstream f(path);if(!f)return false;unordered_map<string,string> m;string s;while(getline(f,s)){s=trim(s);if(s.empty()||s[0]=='#')continue;size_t p=s.find('=');if(p==string::npos)return false;string k=trim(s.substr(0,p)),v=trim(s.substr(p+1));if(k.empty()||v.empty()||m.count(k))return false;m[k]=v;}if(f.bad()||m.size()!=9)return false;const char*keys[]={"listen","root","max_connections","header_bytes","header_timeout_ms","idle_timeout_ms","write_timeout_ms","max_requests","pipeline_depth"};for(auto k:keys)if(!m.count(k))return false;c.listen=m["listen"];c.root=m["root"];if(c.root.empty()||c.root[0]!='/')return false;struct stat st;if(stat(c.root.c_str(),&st)||!S_ISDIR(st.st_mode))return false;return number(m["max_connections"],c.maxconn)&&number(m["header_bytes"],c.header)&&number(m["header_timeout_ms"],c.htime)&&number(m["idle_timeout_ms"],c.idle)&&number(m["write_timeout_ms"],c.wtime)&&number(m["max_requests"],c.maxreq)&&number(m["pipeline_depth"],c.pipe);}
static bool tokenchar(unsigned char c){return (c>='a'&&c<='z')||(c>='A'&&c<='Z')||(c>='0'&&c<='9')||strchr("!#$%&'*+-.^_`|~",c);}
static bool utf8(const string&s){for(size_t i=0;i<s.size();){unsigned char c=s[i++];if(c<0x80)continue;int n;uint32_t x,min;if(c>=0xc2&&c<=0xdf){n=1;x=c&31;min=0x80;}else if(c>=0xe0&&c<=0xef){n=2;x=c&15;min=0x800;}else if(c>=0xf0&&c<=0xf4){n=3;x=c&7;min=0x10000;}else return false;if(i+n>s.size())return false;while(n--){unsigned char d=s[i++];if((d&0xc0)!=0x80)return false;x=(x<<6)|(d&63);}if(x<min||x>0x10ffff||(x>=0xd800&&x<=0xdfff))return false;}return true;}
static int hex(unsigned char c){if(c>='0'&&c<='9')return c-'0';if(c>='a'&&c<='f')return c-'a'+10;if(c>='A'&&c<='F')return c-'A'+10;return -1;}
static int parse(const string& in,string& path){size_t end=in.find("\r\n\r\n");if(end==string::npos)return 400;size_t line=in.find("\r\n");if(line==string::npos||line>end)return 400;string_view first(in.data(),line);size_t a=first.find(' '),b=a==string_view::npos?a:first.find(' ',a+1);if(a==string_view::npos||b==string_view::npos||a==0||b==a+1||first.find(' ',b+1)!=string_view::npos)return 400;string_view method=first.substr(0,a),target=first.substr(a+1,b-a-1),version=first.substr(b+1);for(unsigned char c:method)if(!tokenchar(c))return 400;if(version!="HTTP/1.0"&&version!="HTTP/1.1")return 400;if(target.empty()||target[0]!='/'||target.find('#')!=string_view::npos)return 400;for(unsigned char c:target)if(c<=32||c==127)return 400;
 size_t pos=line+2;bool cl=false;while(pos<end){size_t e=in.find("\r\n",pos);if(e==string::npos||e>end||e==pos)return 400;size_t colon=in.find(':',pos);if(colon==string::npos||colon>=e||colon==pos)return 400;for(size_t i=pos;i<colon;i++)if(!tokenchar((unsigned char)in[i]))return 400;for(size_t i=colon+1;i<e;i++){unsigned char c=in[i];if((c<32&&c!='\t')||c==127)return 400;}string name=in.substr(pos,colon-pos);for(char&c:name)if(c>='A'&&c<='Z')c+=32;size_t l=colon+1,r=e;while(l<r&&(in[l]==' '||in[l]=='\t'))l++;while(r>l&&(in[r-1]==' '||in[r-1]=='\t'))r--;if(name=="transfer-encoding")return 400;if(name=="content-length"){if(cl||l==r)return 400;cl=true;for(size_t i=l;i<r;i++)if(in[i]!='0')return 400;}pos=e+2;}
 size_t q=target.find('?');string_view raw=target.substr(0,q);path.clear();path.reserve(raw.size());for(size_t i=0;i<raw.size();i++){unsigned char c=raw[i];if(c=='%'){if(i+2>=raw.size())return 400;int x=hex(raw[i+1]),y=hex(raw[i+2]);if(x<0||y<0)return 400;c=(x<<4)|y;i+=2;}if(c==0||c=='\\')return 400;path.push_back(c);}if(!utf8(path))return 400;size_t i=1;while(i<=path.size()){size_t j=path.find('/',i);if(j==string::npos)j=path.size();if(path.compare(i,j-i,"..")==0)return 403;if(j==path.size())break;i=j+1;}if(method!="GET")return 405;return 200;}
struct Cache {dev_t dev;ino_t ino;off_t size;timespec mt,ct;shared_ptr<string> data;};
struct Conn {int fd=-1,file=-1;uint32_t gen=0;string input,head;size_t hoff=0,boff=0;off_t filepos=0,filesize=0;shared_ptr<string> body;bool writing=false;uint64_t deadline=0;};
struct Timer {uint64_t t;int fd;uint32_t gen;bool writing;bool operator<(const Timer&o)const{return t>o.t;}};
static uint64_t addtime(uint64_t a,uint64_t b){return UINT64_MAX-a<b?UINT64_MAX:a+b;}
class Server {Config c;int ep=-1,root=-1,ls=-1;uint32_t nextgen=0;size_t active=0,cachebytes=0;unordered_map<int,Conn> conns;unordered_map<string,Cache> cache;priority_queue<Timer> timers;
 void closeconn(int fd){auto it=conns.find(fd);if(it==conns.end())return;epoll_ctl(ep,EPOLL_CTL_DEL,fd,nullptr);close(fd);if(it->second.file>=0)close(it->second.file);conns.erase(it);active--;}
 void events(Conn&x,uint32_t ev){epoll_event e{};e.events=ev|EPOLLRDHUP;e.data.u64=((uint64_t)x.gen<<32)|(uint32_t)x.fd;epoll_ctl(ep,EPOLL_CTL_MOD,x.fd,&e);}
 void response(Conn&x,int status,off_t size=0){const char*reason=status==200?"OK":status==400?"Bad Request":status==403?"Forbidden":status==404?"Not Found":status==405?"Method Not Allowed":status==431?"Request Header Fields Too Large":"Internal Server Error";if(status!=200)size=0;x.head="HTTP/1.1 "+to_string(status)+" "+reason+"\r\nContent-Length: "+to_string(size)+"\r\nConnection: close\r\n"+(status==200?"Content-Type: application/octet-stream\r\n":"")+"\r\n";x.writing=true;x.deadline=addtime(nowms(),c.wtime);timers.push({x.deadline,x.fd,x.gen,true});events(x,EPOLLOUT);}
 int openfile(const string&path,struct stat&st){int dir=dup(root);if(dir<0)return -500;size_t i=1;vector<string> parts;while(i<path.size()){size_t j=path.find('/',i);if(j==string::npos)j=path.size();string s=path.substr(i,j-i);if(!s.empty()&&s!=".")parts.push_back(s);i=j+1;}if(parts.empty()){close(dir);return -403;}for(size_t n=0;n<parts.size();n++){bool last=n+1==parts.size();int fd=openat(dir,parts[n].c_str(),O_RDONLY|O_CLOEXEC|O_NOFOLLOW|O_NONBLOCK|(last?0:O_DIRECTORY));int er=errno;if(fd<0){if(er==ENOTDIR){struct stat s;if(fstatat(dir,parts[n].c_str(),&s,AT_SYMLINK_NOFOLLOW)==0&&(S_ISLNK(s.st_mode)||!S_ISDIR(s.st_mode)))er=EACCES;}close(dir);return er==ELOOP||er==EACCES||er==EPERM?-403:er==ENOENT||er==ENOTDIR||er==ENAMETOOLONG?-404:-500;}close(dir);dir=fd;}if(fstat(dir,&st)){close(dir);return -500;}if(!S_ISREG(st.st_mode)){close(dir);return -403;}if(!path.empty()&&path.back()=='/'){close(dir);return -403;}return dir;}
 void serve(Conn&x,const string&path){struct stat st;int f=openfile(path,st);if(f<0){response(x,-f);return;}if(st.st_size<0){close(f);response(x,500);return;}x.filesize=st.st_size;if(st.st_size<=131072){auto it=cache.find(path);bool hit=it!=cache.end()&&it->second.dev==st.st_dev&&it->second.ino==st.st_ino&&it->second.size==st.st_size&&it->second.mt.tv_sec==st.st_mtim.tv_sec&&it->second.mt.tv_nsec==st.st_mtim.tv_nsec&&it->second.ct.tv_sec==st.st_ctim.tv_sec&&it->second.ct.tv_nsec==st.st_ctim.tv_nsec;if(hit)x.body=it->second.data;else{auto data=make_shared<string>();data->resize((size_t)st.st_size);size_t off=0;while(off<data->size()){ssize_t n=pread(f,data->data()+off,data->size()-off,off);if(n>0)off+=n;else if(n<0&&errno==EINTR)continue;else {close(f);response(x,500);return;}}if(cachebytes+data->size()>32*1024*1024){cache.clear();cachebytes=0;}if(it!=cache.end()&&cache.count(path)){cachebytes-=cache[path].data->size();cache.erase(path);}cachebytes+=data->size();cache[path]={st.st_dev,st.st_ino,st.st_size,st.st_mtim,st.st_ctim,data};x.body=data;}close(f);}else x.file=f;response(x,200,st.st_size);}
 bool writeout(Conn&x){while(x.hoff<x.head.size()||(x.body&&x.boff<x.body->size())||(x.file>=0&&x.filepos<x.filesize)){ssize_t n;if(x.file>=0&&x.hoff==x.head.size()){n=sendfile(x.fd,x.file,&x.filepos,(size_t)min<off_t>(x.filesize-x.filepos,1<<20));}else {iovec v[2];int count=0;if(x.hoff<x.head.size())v[count++]={(void*)(x.head.data()+x.hoff),x.head.size()-x.hoff};if(x.body&&x.boff<x.body->size())v[count++]={(void*)(x.body->data()+x.boff),x.body->size()-x.boff};n=writev(x.fd,v,count);if(n>0){size_t z=n,h=min(z,x.head.size()-x.hoff);x.hoff+=h;z-=h;x.boff+=z;}}if(n>0)continue;if(n<0&&errno==EINTR)continue;if(n<0&&(errno==EAGAIN||errno==EWOULDBLOCK))return false;return true;}return true;}
 void readin(Conn&x){char buf[16384];while(true){ssize_t n=recv(x.fd,buf,sizeof(buf),0);if(n>0){x.input.append(buf,n);size_t end=x.input.find("\r\n\r\n");size_t relevant=end==string::npos?x.input.size():end+4;for(size_t i=0;i<relevant;i++){unsigned char z=x.input[i];if(z==0||(z=='\n'&&(i==0||x.input[i-1]!='\r'))||(z=='\r'&&i+1<relevant&&x.input[i+1]!='\n')){response(x,400);return;}}if(end!=string::npos){if(end+4>c.header){response(x,431);return;}string path;int code=parse(x.input,path);if(code!=200)response(x,code);else serve(x,path);return;}if(x.input.size()>=c.header){response(x,431);return;}continue;}if(n==0){closeconn(x.fd);return;}if(errno==EINTR)continue;if(errno==EAGAIN||errno==EWOULDBLOCK)return;closeconn(x.fd);return;}}
 public:Server(Config cc):c(move(cc)){}int run(){signal(SIGPIPE,SIG_IGN);root=open(c.root.c_str(),O_RDONLY|O_DIRECTORY|O_CLOEXEC);if(root<0)return 1;size_t p=c.listen.rfind(':');if(p==string::npos)return 1;string ip=c.listen.substr(0,p),port=c.listen.substr(p+1);uint64_t pn;if(!number(port,pn)||pn>65535)return 1;sockaddr_in addr{};addr.sin_family=AF_INET;addr.sin_port=htons(pn);if(inet_pton(AF_INET,ip.c_str(),&addr.sin_addr)!=1)return 1;ls=socket(AF_INET,SOCK_STREAM|SOCK_NONBLOCK|SOCK_CLOEXEC,0);if(ls<0)return 1;int one=1;setsockopt(ls,SOL_SOCKET,SO_REUSEADDR,&one,sizeof(one));if(bind(ls,(sockaddr*)&addr,sizeof(addr))||listen(ls,8192))return 1;ep=epoll_create1(EPOLL_CLOEXEC);if(ep<0)return 1;epoll_event e{};e.events=EPOLLIN;e.data.u64=0;if(epoll_ctl(ep,EPOLL_CTL_ADD,ls,&e))return 1;array<epoll_event,1024> evs;while(true){uint64_t now=nowms();while(!timers.empty()&&timers.top().t<=now){auto t=timers.top();timers.pop();auto it=conns.find(t.fd);if(it!=conns.end()&&it->second.gen==t.gen&&it->second.writing==t.writing&&it->second.deadline==t.t)closeconn(t.fd);}int timeout=-1;if(!timers.empty()){uint64_t d=timers.top().t>now?timers.top().t-now:0;timeout=(int)min<uint64_t>(d,INT_MAX);}int n=epoll_wait(ep,evs.data(),evs.size(),timeout);if(n<0){if(errno==EINTR)continue;return 1;}for(int k=0;k<n;k++){uint64_t key=evs[k].data.u64;if(!key){while(true){int fd=accept4(ls,nullptr,nullptr,SOCK_NONBLOCK|SOCK_CLOEXEC);if(fd<0){if(errno==EINTR)continue;break;}if(active>=c.maxconn){close(fd);continue;}Conn x;x.fd=fd;x.gen=++nextgen;if(!x.gen)x.gen=++nextgen;x.deadline=addtime(nowms(),c.htime);uint32_t gen=x.gen;uint64_t deadline=x.deadline;conns.emplace(fd,move(x));active++;epoll_event q{};q.events=EPOLLIN|EPOLLRDHUP;q.data.u64=((uint64_t)gen<<32)|(uint32_t)fd;if(epoll_ctl(ep,EPOLL_CTL_ADD,fd,&q)){closeconn(fd);continue;}timers.push({deadline,fd,gen,false});}continue;}int fd=(uint32_t)key;uint32_t gen=key>>32;auto it=conns.find(fd);if(it==conns.end()||it->second.gen!=gen)continue;Conn&x=it->second;if(!x.writing){if(nowms()>=x.deadline){closeconn(fd);continue;}readin(x);it=conns.find(fd);if(it==conns.end())continue;}if(it->second.writing){if(nowms()>=it->second.deadline||writeout(it->second))closeconn(fd);}}}return 0;}};
int main(int argc,char**argv){if(argc!=3||string(argv[1])!="--config")return 1;Config c;if(!config(argv[2],c))return 1;return Server(move(c)).run();}
